<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {service,dataMode} from '../services'
import {errorText,confirmAction} from '../composables/useData'
import type {Message,Session,ChatEvent,Citation} from '../types/domain'
import PageHeader from '../components/PageHeader.vue'
import SafeMarkdown from '../components/SafeMarkdown.vue'
import Brand from '../components/Brand.vue'
import Icon from '../components/Icon.vue'
const sessions=ref<Session[]>([]),currentId=ref<string>(),messages=ref<Message[]>([]),question=ref(''),error=ref(''),streaming=ref(false),loading=ref(true),historyOpen=ref(false),messageBox=ref<HTMLDivElement>(),controller=ref<AbortController>(),disposed=ref(false),autoScroll=ref(true)
const citations=computed(()=>messages.value.filter(m=>m.role==='assistant').at(-1)?.citations||[])
async function load(){loading.value=true;try{sessions.value=(await service.list('sessions')).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));if(!streaming.value&&currentId.value){const current=sessions.value.find(s=>s.id===currentId.value);messages.value=current?JSON.parse(JSON.stringify(current.messages)):[]}}catch(e){error.value=errorText(e);messages.value=[]}finally{loading.value=false}}
function revalidate(){if(!streaming.value){if(currentId.value)messages.value=[];void load()}}
onMounted(()=>{void load();window.addEventListener('focus',revalidate)})
function scroll(){nextTick(()=>{if(autoScroll.value&&messageBox.value)messageBox.value.scrollTop=messageBox.value.scrollHeight})}
function onScroll(){const el=messageBox.value;if(el)autoScroll.value=el.scrollHeight-el.scrollTop-el.clientHeight<100}
function select(session:Session){if(streaming.value)return;currentId.value=session.id;messages.value=JSON.parse(JSON.stringify(session.messages));error.value='';historyOpen.value=false;autoScroll.value=true;scroll()}
function newChat(){if(streaming.value)return;currentId.value=undefined;messages.value=[];question.value='';error.value='';historyOpen.value=false}
async function remove(session:Session){if(!await confirmAction('删除此会话及其消息？','删除会话'))return;try{await service.remove('sessions',[session.id]);if(currentId.value===session.id)newChat();await load()}catch(e){error.value=errorText(e)}}
async function send(){if(streaming.value||!question.value.trim())return;const text=question.value.trim();if(text.length>4000){error.value='问题不能超过 4000 字';return}question.value='';error.value='';autoScroll.value=true;streaming.value=true;controller.value=new AbortController();messages.value.push({id:crypto.randomUUID(),role:'user',text,citations:[],denied:false});const answerId=crypto.randomUUID();messages.value.push({id:answerId,role:'assistant',text:'',citations:[],denied:false});const answer=()=>messages.value.find(m=>m.id===answerId)!;scroll()
 let finished=false
 function event(e:ChatEvent){if(disposed.value)return;if(e.type==='session')currentId.value=e.sessionId;if(e.type==='delta')answer().text+=e.text;if(e.type==='citations')answer().citations=e.citations;if(e.type==='denied')answer().denied=true;if(e.type==='cache')answer().cached=e.hit;if(e.type==='done')finished=true;scroll()}
 try{await service.streamChat(text,currentId.value,event,controller.value.signal);if(!finished)throw new Error('回答尚未完成，请重试')}catch(e){answer().interrupted=true;if((e as Error).name!=='AbortError')error.value=errorText(e);if(!answer().text)answer().text='回答已中断。你可以重新提问。'}finally{streaming.value=false;controller.value=undefined;if(!disposed.value)await load()}}
function keydown(e:KeyboardEvent){if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();void send()}}
function stop(){controller.value?.abort()}
onBeforeUnmount(()=>{disposed.value=true;stop();window.removeEventListener('focus',revalidate)})
function useSuggestion(text:string){question.value=text;void send()}
</script>
<template><PageHeader title="AI 对话" description="基于你有权访问的知识回答，并保留每一个引用来源。"><button class="btn quiet history-toggle" @click="historyOpen=!historyOpen"><Icon name="clock"/>历史会话</button><button class="btn quiet" :disabled="streaming" @click="newChat"><Icon name="plus"/>新建会话</button></PageHeader><div class="chat-layout"><aside class="panel chat-history" :class="{expanded:historyOpen}"><div class="panel-head"><h2>历史会话</h2><span class="small faint">{{sessions.length}}</span></div><p v-if="loading" class="small faint">正在加载…</p><p v-else-if="!sessions.length" class="small faint">开始一次提问，记录会保存在这里。</p><div v-for="session in sessions" :key="session.id" class="history-row" :class="{active:currentId===session.id}"><button :disabled="streaming" @click="select(session)"><strong>{{session.title}}</strong><small>{{new Date(session.updatedAt).toLocaleDateString('zh-CN')}}</small></button><button class="icon-button" aria-label="删除会话" :disabled="streaming" @click="remove(session)"><Icon name="close" :size="13"/></button></div></aside><section class="panel chat-panel"><div class="chat-heading"><span><i class="live-dot"/>知识助手</span><small>{{dataMode==='demo'?'模拟问答':'团队知识问答'}}</small></div><div ref="messageBox" class="messages" aria-live="polite" aria-relevant="additions" @scroll="onScroll"><div v-if="!messages.length" class="chat-welcome"><Icon name="book" :size="42"/><h2>从一个问题开始。</h2><p>我会依据获授权的团队知识作答，<br>并告诉你答案来自哪里。</p><div class="suggestions"><button @click="useSuggestion('差旅报销需要哪些材料？')">差旅报销需要哪些材料？<Icon name="arrow" :size="14"/></button><button @click="useSuggestion('新同事入职要做什么？')">新同事入职要做什么？<Icon name="arrow" :size="14"/></button><button @click="useSuggestion('研发环境如何接入？')">研发环境如何接入？<Icon name="arrow" :size="14"/></button></div></div><article v-for="message in messages" :key="message.id" class="message" :class="message.role"><template v-if="message.role==='user'"><p>{{message.text}}</p></template><template v-else><div class="assistant-label"><span class="mini-pixel"/><strong>知识助手</strong><span v-if="message.cached" class="status success">{{dataMode==='demo'?'演示 FAQ 命中':'FAQ 缓存命中'}}</span></div><SafeMarkdown v-if="message.text" :content="message.text"/><div v-else class="small faint" role="status">正在检索授权知识…</div><p v-if="message.denied" class="notice warning message-note">部分相关资料尚未授权，未纳入回答。请联系知识管理员申请访问。</p><p v-if="message.interrupted" class="small faint">此条回复已中断。</p><div v-if="message.citations.length" class="citation-links"><RouterLink v-for="citation in message.citations" :key="citation.unitId" :to="`/knowledge/units/${citation.unitId}`">{{citation.code}} · {{citation.title}} ↗</RouterLink></div></template></article></div><p v-if="error" role="alert" class="notice error" style="margin-bottom:12px">{{error}}</p><form class="composer" @submit.prevent="send"><textarea v-model="question" aria-label="输入问题" placeholder="向团队知识提问…" maxlength="4000" @keydown="keydown"/><div class="composer-footer"><small>Enter 发送 · Shift + Enter 换行</small><button v-if="streaming" type="button" class="btn quiet small" @click="stop">停止回答</button><button v-else class="btn primary small" :disabled="!question.trim()">发送<Icon name="arrow" :size="15"/></button></div></form><p class="chat-footnote">{{dataMode==='demo'?'本地演示回复，未调用模型；请勿将演示样本作为真实业务依据。':'回答可能存在遗漏，请结合引用原文确认。'}}</p></section><aside class="panel chat-sources"><div class="panel-head"><h2>引用来源</h2><span class="small faint">{{citations.length}} 项</span></div><p v-if="!citations.length" class="small faint">提问后，已授权的知识来源将显示在这里。</p><RouterLink v-for="citation in citations" :key="citation.unitId" :to="`/knowledge/units/${citation.unitId}`" class="source-card"><span>{{citation.code}}</span><h3>{{citation.title}}</h3><p>{{citation.location}}</p><small>查看知识原文 ↗</small></RouterLink><div class="source-explanation"><Icon name="shield"/><h3>授权决定回答范围</h3><p>仅使用你有权访问且已发布的知识。未获授权的资料不展示正文、摘要或标题。</p></div></aside></div></template>
<style scoped>.chat-layout{display:grid;grid-template-columns:190px minmax(0,1fr) 238px;gap:20px}.chat-history,.chat-sources{padding:18px}.chat-history h2,.chat-sources h2{font-size:14px}.history-row{display:flex;align-items:center;margin-bottom:6px;border-radius:3px}.history-row.active,.history-row:hover{background:var(--raised)}.history-row>button:first-child{border:0;background:transparent;text-align:left;padding:12px 8px;min-width:0;flex:1}.history-row strong{font-size:12px;font-weight:400;display:block;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.history-row small{font-size:11px;color:var(--faint);display:block;margin-top:8px}.history-row .icon-button{padding:5px}.chat-panel{display:flex;flex-direction:column;min-height:calc(100dvh - 244px);padding:20px}.chat-heading{display:flex;align-items:center;justify-content:space-between;padding-bottom:18px;border-bottom:1px solid var(--line)}.chat-heading>span{font-size:13px;display:flex;align-items:center;gap:9px}.chat-heading>small{font-size:11px;color:var(--faint)}.messages{height:calc(100dvh - 460px);min-height:340px;overflow:auto;overscroll-behavior:contain;display:flex;flex-direction:column;gap:28px;padding:24px 0;margin-bottom:16px}.message.user{align-self:flex-end;max-width:90%;padding:12px 16px;background:var(--raised);border-radius:4px;font-size:14px;line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere}.message.assistant{font-size:14px;max-width:100%}.assistant-label{display:flex;align-items:center;gap:9px;margin-bottom:16px}.assistant-label strong{font-size:12px;font-weight:500}.mini-pixel{width:14px;height:14px;background:var(--accent);clip-path:polygon(0 0,40% 0,40% 40%,60% 40%,60% 0,100% 0,100% 100%,60% 100%,60% 60%,40% 60%,40% 100%,0 100%)}.composer{border:1px solid #60756a;border-radius:4px;padding:12px;background:var(--bg);margin-top:auto}.composer textarea{background:none;border:0;outline:0;width:100%;min-height:56px;padding:0;resize:none;font-size:14px;line-height:1.8}.composer-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:10px}.composer-footer small{font-size:10px;color:var(--faint)}.chat-footnote{font-size:11px;color:var(--faint);margin-top:10px;line-height:1.8}.chat-welcome{display:flex;flex-direction:column;align-items:flex-start;padding:20px 10px;max-width:400px;margin:auto;width:100%}.chat-welcome>svg{color:var(--accent);margin-bottom:24px}.chat-welcome h2{font-size:22px}.chat-welcome>p{font-size:13px;color:var(--muted);line-height:1.9;margin-top:12px}.suggestions{display:grid;gap:8px;width:100%;margin-top:24px}.suggestions button{display:flex;justify-content:space-between;align-items:center;gap:20px;background:none;border:1px solid var(--line);font-size:12px;padding:11px 12px;border-radius:3px;text-align:left}.suggestions button:hover{background:var(--raised)}.source-card{display:block;padding:16px;background:var(--raised);border-radius:3px;margin-top:16px}.source-card>span{font-size:11px;color:var(--faint)}.source-card h3{font-size:13px;line-height:1.8;margin-top:8px}.source-card p,.source-card small{font-size:11px;color:var(--faint);margin-top:8px;display:block}.source-card small{color:var(--accent)}.source-explanation{margin-top:36px}.source-explanation>svg{color:var(--faint);margin-bottom:12px}.source-explanation h3{font-size:12px}.source-explanation p{font-size:12px;color:var(--muted);line-height:1.9;margin-top:12px}.citation-links{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.citation-links a{font-size:11px;color:var(--accent);background:var(--raised);padding:6px 9px;border-radius:3px;line-height:1.8}.message-note{margin-top:16px}.history-toggle{display:none}@media(max-width:1200px){.chat-layout{grid-template-columns:170px minmax(0,1fr)}.chat-sources{grid-column:1/-1;display:flex;gap:20px;align-items:flex-start;flex-wrap:wrap}.chat-sources .panel-head{width:100%;margin:0}.source-card{flex:1;min-width:170px;margin:0}.source-explanation{flex:1;margin:0;min-width:160px}}@media(max-width:640px){.chat-layout{display:flex;flex-direction:column}.history-toggle{display:inline-flex}.chat-history{display:none}.chat-history.expanded{display:block}.chat-panel{padding:16px;min-height:600px}.messages{height:420px;min-height:320px}.chat-welcome{padding:20px 0}.chat-welcome h2{font-size:20px}.composer-footer small{font-size:10px}.chat-sources{display:block}.source-explanation{margin-top:26px}.source-card{margin-top:16px}.chat-history.expanded{max-height:300px;overflow:auto}}
</style>
